import math

class VEB:
    # Requires u to be an exact power of two whose exponent is itself
    # a power of two (u = 4, 16, 256, 65536, ...), so sqrt(u) splits evenly.
    def __init__(self, u):
        self.u = u
        self.min = self.max = None
        if u > 2:
            self.upper = math.isqrt(u)          # cluster count == cluster size
            self.cluster = [None] * self.upper   # lazily allocated
            self.summary = None

    def _high(self, x): return x // self.upper
    def _low(self, x):  return x % self.upper
    def _index(self, i, j): return i * self.upper + j

    def member(self, x):
        if x == self.min or x == self.max:
            return True
        if self.u == 2 or self.min is None:
            return False
        c = self.cluster[self._high(x)]
        return c is not None and c.member(self._low(x))

    def insert(self, x):
        if self.min is None:
            self.min = self.max = x
            return
        if x < self.min:
            x, self.min = self.min, x
        if self.u > 2:
            i, j = self._high(x), self._low(x)
            if self.cluster[i] is None:
                self.cluster[i] = VEB(self.upper)
            if self.cluster[i].min is None:      # cluster was empty:
                if self.summary is None:
                    self.summary = VEB(self.upper)
                self.summary.insert(i)            # ...mark it in summary
                self.cluster[i].min = self.cluster[i].max = j   # O(1), no recursion
            else:
                self.cluster[i].insert(j)         # cluster nonempty: recurse, skip summary
        if x > self.max:
            self.max = x

    def successor(self, x):
        if self.u == 2:
            return 1 if x == 0 and self.max == 1 else None
        if self.min is not None and x < self.min:
            return self.min
        i, j = self._high(x), self._low(x)
        c = self.cluster[i]
        if c is not None and c.max is not None and j < c.max:
            return self._index(i, c.successor(j))
        nxt = self.summary.successor(i) if self.summary is not None else None
        if nxt is None:
            return None
        return self._index(nxt, self.cluster[nxt].min)
